// Package records serves a repo's entire-records stores from this cell's
// Postgres projection of them.
//
// The decode is entire-records', imported over its store.Projection seam and
// never reimplemented here. Every read first catches the projection up, so a
// landed write is visible to the next read.
package records

import (
	"context"
	"fmt"

	"github.com/entirehq/entire-records/recordapi"
	recschema "github.com/entirehq/entire-records/schema"
	recstore "github.com/entirehq/entire-records/store"

	"github.com/entirehq/entire-api/internal/recordchange"
)

// Source is where a read finds a store (recordprojection.Reads).
type Source interface {
	// Open catches one store's projection up and returns a view of that state
	// alone, so everything one request decodes agrees with its tip. The caller
	// must call Release; on error there is nothing to release.
	Open(ctx context.Context, repoID, store string) (Opened, error)
	// Stores names every strata store in the repo, records or not: sorted,
	// each once.
	Stores(ctx context.Context, repoID string) ([]string, error)
}

// Opened is one state of a store, held until Release.
type Opened struct {
	Projection   recstore.Projection
	At           State
	ChangedSince func(tick uint64) ([]recordchange.Record, error)
	Release      func()
}

// State says where a store stands. Tip is equal for equal states; Generation
// and Tick place it for a changes read. Removals digests the expiry and erasure
// sets, which delete rows rather than write them, so no tick can tell them.
type State struct {
	Tip        string
	Generation uint64
	Tick       uint64
	Removals   string
}

// Reader answers records reads for a repo's stores.
type Reader struct{ src Source }

// New builds a Reader over a source of projections.
func New(src Source) *Reader { return &Reader{src: src} }

type SchemaResult struct {
	Tip     string
	Version int
	Schema  recordapi.SchemaDTO
}

type recordDTO = recordapi.RecordDTO

// CollectionsResult is one page of records, all from one state of the store.
// Flat rather than keyed by type, so that it can be paged.
type CollectionsResult struct {
	Tip          string
	ChangesToken string
	Records      []recordDTO
	NextToken    string
}
